<script setup lang="ts">
import {ref} from 'vue';import {useRouter,useRoute} from 'vue-router';import {login} from '../session';import {errorText} from '../ui';import Icon from '../components/Icon.vue';
const username=ref(''),password=ref(''),busy=ref(false),error=ref('');const router=useRouter(),route=useRoute();
async function submit(){busy.value=true;error.value='';try{await login(username.value.trim(),password.value);const target=typeof route.query.redirect==='string'&&route.query.redirect.startsWith('/')&&!route.query.redirect.startsWith('//')?route.query.redirect:'/dashboard';await router.replace(target);}catch(e){error.value=errorText(e);}finally{busy.value=false;}}
</script>
<template><main class="login-page"><section class="login-story"><a class="brand" href="/">寓见<span>DormLink</span></a><div><p class="section-note">学生公寓综合服务管理平台</p><h1>公寓里的日常，<br>有序照应。</h1><p>入住、来访、巡检与报修，在同一处清楚办理。</p></div><figure><img src="/assets/images/campus-courtyard.jpg" alt="庭院树影与暖色建筑，校园生活氛围示意"><figcaption>校园生活氛围示意 · <a href="/assets/images/SOURCES.md" target="_blank">图片来源与许可</a></figcaption></figure></section><section class="login-form"><form @submit.prevent="submit"><div class="login-icon"><Icon name="building"/></div><p class="section-note">宿管管理端</p><h2>欢迎回来</h2><p class="muted">使用宿管账号登录，查看负责楼栋的服务事项。</p><label>账号<input v-model="username" name="username" required autocomplete="username" maxlength="80" placeholder="请输入宿管账号"></label><label>密码<input v-model="password" name="password" type="password" required autocomplete="current-password" maxlength="128" placeholder="请输入登录密码"></label><div v-if="error" class="error-banner" role="alert">{{error}}</div><button class="btn primary full" type="submit" :disabled="busy">{{busy?'正在登录…':'登录管理端'}}<Icon name="arrow"/></button><p class="form-note">账号与楼栋范围由学校配置。学生服务请使用鸿蒙端。</p></form><span class="login-footer">寓见 · 公寓服务工作台</span></section></main></template>
